const D = { density:.55, scale:1, speed:1, energy:.6, hue:130, x:.5, y:.5, style:'terminal', seed:0, reveal:.6, act:'storm' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const GLY = "01</>{}[]#$%&*+=|\\:;~^?!.aｦｱ";
const st = P.style;
const dark = (st!=='paper');

// ---- cached background (CRT phosphor / paper / thermal ground) ----
const bgkey = width+'x'+height+':'+st+':'+Math.round(P.hue);
if (!S.bg || S.bgKey !== bgkey) {
  const g = createGraphics(width, height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  if (st==='paper') g.background(42,9,84);
  else if (st==='amber') g.background(32,55,5);
  else if (st==='thermal') g.background(250,55,4);
  else if (st==='mono') g.background(0,0,3);
  else g.background((P.hue)%360,72,4);
  // vignette
  for (let r=8;r>0;r--){ g.fill(0,0, dark?0:20, dark?4:3); g.ellipse(width/2,height/2, width*(0.7+r*0.09), height*(0.75+r*0.09)); }
  // scanlines for CRT styles
  if (dark){ g.stroke(0,0,0,34); g.strokeWeight(1); const sp=Math.max(2,u*0.006); for (let y=0;y<height;y+=sp) g.line(0,y,width,y); }
  S.bg=g; S.bgKey=bgkey;
}
image(S.bg,0,0);

// ---- grid geometry ----
const cell = Math.max(12, u*0.03*P.scale*(1.28-0.55*P.density));
const cols = Math.min(160, Math.ceil(width/cell)+1);
const rows = Math.min(120, Math.ceil(height/cell)+1);

// ---- per-column drop state (seed + col-count keyed) ----
if (!S.nc || S.nc!==cols || S.seedUsed!==P.seed){
  S.nc=cols; S.seedUsed=P.seed; S.cspd=[]; S.coff=[]; S.cact=[];
  for (let c=0;c<cols;c++){ S.cspd[c]=0.55+fr(c*3+1)*1.6; S.coff[c]=fr(c*7+2)*(rows+8); S.cact[c]=fr(c*11+5); }
}

// ---- reveal mask (word / shape) rebuilt per section ----
if (!S.mbuf || S.mw!==cols || S.mh!==rows){ if(S.mbuf&&S.mbuf.remove)S.mbuf.remove(); S.mbuf=createGraphics(cols,rows); S.mbuf.colorMode(HSB,360,100,100,100); S.mw=cols; S.mh=rows; S.mkey=null; }
const sec = K.section|0;
const mkey = cols+'x'+rows+':'+sec+':'+(P.seed|0)+':'+Math.round(P.x*20)+':'+Math.round(P.y*20);
if (S.mkey!==mkey){
  S.mkey=mkey; const m=S.mbuf; m.background(0,0,0); m.noStroke(); m.fill(0,0,100);
  const cx=cols*P.x, cy=rows*P.y, R=Math.min(cols,rows)*0.42;
  const idx=(sec + (P.seed|0)*3)%8;
  if (idx%2===0){
    const words=["LIVE","CODE","RAIN","NULL","ECHO","SYNC","VOID","0xF"];
    m.textAlign(CENTER,CENTER); m.textStyle(BOLD); m.textFont('monospace');
    m.textSize(rows*0.52); m.text(words[idx%words.length], cx, cy);
  } else {
    const gi=idx%4;
    if (gi===1){ m.noFill(); m.stroke(0,0,100); m.strokeWeight(Math.max(1,cols*0.035)); m.ellipse(cx,cy,R*2,R*2); m.strokeWeight(Math.max(1,cols*0.02)); m.ellipse(cx,cy,R*1.0,R*1.0); }
    else if (gi===3){ for(let k=0;k<5;k++){ m.rect(cx-R*0.9 + k*R*0.42, cy-R, R*0.16, R*2); } }
    else { m.triangle(cx, cy-R, cx-R, cy+R*0.85, cx+R, cy+R*0.85); }
  }
  m.loadPixels();
  const mg=new Uint8Array(cols*rows), pd=m.pixelDensity?m.pixelDensity():1;
  for (let yy=0;yy<rows;yy++) for (let xx=0;xx<cols;xx++){ const pi=4*((yy*pd)*(cols*pd)+(xx*pd)); mg[yy*cols+xx]=(m.pixels[pi]>60)?1:0; }
  S.mg=mg;
}

// ---- reveal envelope + act dramaturgy ----
let rev = P.reveal;
if (P.act==='broadcast') rev *= (0.6+0.4*K.swell);
else if (P.act==='decay') rev *= (0.25+0.75*(1-((sec%4)/3)));
else rev *= (0.12+0.88*Math.pow(K.swell,1.6)); // storm: surfaces on the swell
rev = Math.max(0, Math.min(1, rev));
let actFrac = 1;
if (P.act==='decay') actFrac = 0.4+0.6*(1-((sec%4)/3));

const glow = 0.55 + 0.45*P.energy + A.treble*0.55;
const activeThresh = (0.28 + P.density*0.66) * actFrac;
const T = Math.min(30, Math.round(5 + P.density*20));
const churn = 2 + P.speed*2;

blendMode(dark?ADD:BLEND);
noStroke(); textAlign(CENTER,CENTER); textFont('monospace'); textSize(cell*0.86);
const gcx = cell*0.5, gcy = cell*0.5;

function gfill(level, head){
  level=level<0?0:(level>1?1:level);
  if (st==='paper'){ fill(220,14+level*16, 90-level*74, 92); return; }
  if (st==='thermal'){ const h=(1-level)*208+level*16; fill(h%360, 92-level*32, 22+level*78, 86); return; }
  if (st==='amber'){ fill(35, head?38:88, head?100:(24+level*72), 88); return; }
  if (st==='mono'){ fill(0,0, head?100:(22+level*74), 88); return; }
  fill((P.hue)%360, head?22:78, head?100:(22+level*74), 88);
}

let budget = 2500;
// falling drops
for (let c=0; c<cols && budget>0; c++){
  if (S.cact[c] >= activeThresh) continue;
  const spd = S.cspd[c];
  const head = (K.t*P.speed*spd*4.2 + S.coff[c]) % (rows + T + 4);
  const gx = c*cell;
  for (let k=0; k<T && budget>0; k++){
    const row = Math.floor(head) - k;
    if (row<0 || row>=rows) continue;
    const isHead = (k===0);
    const lvl = isHead ? 1 : (1 - k/T)*0.9;
    gfill(lvl*glow, isHead);
    const gi = Math.floor(fr(c*31 + row*17 + Math.floor(K.t*(churn+spd*1.5)))*GLY.length) % GLY.length;
    text(GLY[gi<0?0:gi], gx+gcx, row*cell+gcy);
    budget--;
  }
}
// mask glyphs — the shape surfacing through the rain
if (rev>0.04 && S.mg){
  const mg=S.mg; let mb = Math.min(budget, 900);
  const flick = 0.7+0.3*Math.sin(K.t*3.0);
  for (let idx=0; idx<mg.length && mb>0; idx++){
    if (!mg[idx]) continue;
    const xx=idx%cols, yy=(idx/cols)|0;
    gfill(rev*glow*0.9*flick, true);
    const gi = Math.floor(fr(xx*13 + yy*29 + Math.floor(K.t*1.4))*GLY.length) % GLY.length;
    text(GLY[gi<0?0:gi], xx*cell+gcx, yy*cell+gcy);
    mb--; budget--;
  }
}
blendMode(BLEND); drawingContext.shadowBlur=0;
